        val line = scanner.nextLine()
        val parts = line.split(" ")
        if (parts.size < 2) continue
        val n = parts[0].toInt()
        val m = parts[1].toInt()
        when {
            m == 0 || m == 1 -> println(1)
            n == m -> println(0)
            n > 2 * m -> println(m)
            else -> println(n - m)
